/**
 * Client view of the server's WeeklyRecapV2 contract (backend/src/domain/v2/weeklyRecap.ts).
 * The shared fixture in `__fixtures__/weeklyRecapV2.sample.json` is generated by the backend composer and validated by
 * `isWeeklyRecapV2` in the tests, so a contract change fails here instead of rendering wrong.
 */
export type RecapHeroKind =
  | 'DESTINATION_REACHED' | 'ANCHOR_COMPLETED_RELEASED' | 'ANCHOR_RELEASED' | 'ANCHOR_COMPLETED' | 'WAYPOINT_REACHED'
  | 'MOVES_PROGRESS' | 'STRENGTH_MILESTONE' | 'VISION_MILESTONE' | 'PRACTICE_COUNT_MILESTONE' | 'PRACTICE_WEEK' | 'RETURN'
  | 'STEADY' | 'QUIET' | 'INCOMPLETE';
export type RecapStatId = 'PRACTICE_DAYS' | 'PRACTICES' | 'WAYPOINTS' | 'MOVES' | 'COMPLETED' | 'RELEASED' | 'MILESTONES';
export type RecapMarkerKind = 'WAYPOINT' | 'DESTINATION' | 'MOVE' | 'COMPLETED' | 'RELEASED' | 'VISION' | 'MILESTONE';

export type RecapItem = {
  kind: RecapHeroKind; dedupeKey: string; anchorId: string | null; courseId?: string | null; title: string; dateKey: string | null;
  count?: number; movesCompleted?: number; labels: string[];
};
export type WeeklyRecap = {
  recapVersion: 2; templateVersion: number; weekKey: string; timeZone: string;
  range: { startKey: string; endKey: string; label: string };
  status: 'DRAFT' | 'FINAL';
  provisional: { isProvisional: boolean; reason: 'WEEK_IN_PROGRESS' | 'SYNCING' | 'INCOMPLETE_DATA' | null };
  finalizable: boolean; provenance: 'LIVE' | 'RECONSTRUCTED';
  opening: { headline: string; summary: string };
  hero: RecapItem;
  stats: Array<{ id: RecapStatId; value: number; of?: number }>;
  motion: Array<{ dateKey: string; weekday: number; practices: Array<{ id: string; mode: string; anchorId: string | null }>; markers: Array<{ kind: RecapMarkerKind; dedupeKey: string }> }>;
  highlights: RecapItem[]; highlightsOverflow: number;
  anchors: Array<{ anchorId: string; practiceDays: number; practices: number; moves: number; waypoints: number }>; anchorsOverflow: number;
  reflection: { templateId: string; text: string };
  refs: { anchors: Record<string, { intention: string; categoryKey: string; isReleased: boolean }>; charts: Record<string, { anchorId: string | null; destination: string; waypointTotal: number }> };
  dataQuality: { missing: string[] };
};

export type WeeklyRecapEnvelope = { id: string; recap: WeeklyRecap; feedback: string | null; updatedAt: string };
export type WeeklyRecapHistoryItem = { id: string; weekKey: string; label: string; status: 'DRAFT' | 'FINAL'; heroKind: RecapHeroKind; headline: string; provisional: boolean; schemaVersion: 2 };

const isObj = (v: unknown): v is Record<string, any> => typeof v === 'object' && v !== null && !Array.isArray(v);
const isStr = (v: unknown): v is string => typeof v === 'string';
const isItem = (v: unknown): v is RecapItem => isObj(v) && isStr(v.kind) && isStr(v.dedupeKey) && isStr(v.title) && Array.isArray(v.labels);

/** Runtime guard. A payload that fails it is treated as an unavailable recap, never rendered half-understood. */
export function isWeeklyRecap(v: unknown): v is WeeklyRecap {
  return (
    isObj(v) && v.recapVersion === 2 && isStr(v.weekKey) && isStr(v.timeZone) && (v.status === 'DRAFT' || v.status === 'FINAL') &&
    isObj(v.range) && isStr(v.range.label) && isObj(v.provisional) && typeof v.provisional.isProvisional === 'boolean' &&
    isObj(v.opening) && isStr(v.opening.headline) && isStr(v.opening.summary) && isItem(v.hero) &&
    Array.isArray(v.stats) && v.stats.every((s: any) => isObj(s) && isStr(s.id) && typeof s.value === 'number') &&
    Array.isArray(v.motion) && v.motion.length === 7 && Array.isArray(v.highlights) && v.highlights.every(isItem) &&
    Array.isArray(v.anchors) && isObj(v.reflection) && isStr(v.reflection.text) && isObj(v.refs) && isObj(v.refs.anchors) &&
    isObj(v.dataQuality) && Array.isArray(v.dataQuality.missing)
  );
}
